*{box-sizing:border-box} :root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#f7eef2;background:#101013} .dslan-body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 48% 42%,#282028 0%,#151317 48%,#101013 85%)} button{font:inherit;color:inherit;cursor:pointer} button:focus-visible,input:focus-visible{outline:2px solid #f2aac2;outline-offset:5px} .preview{width:min(1000px,calc(100vw - 72px));padding:38px 0 26px}.preview-heading{display:flex;justify-content:space-between;align-items:center;margin:0 3px 18px;color:#9d919b;font:10px "SFMono-Regular",Menlo,monospace;letter-spacing:2.3px}.preview-heading>span:first-child{color:#d3bdc9;display:flex;gap:10px;align-items:center}.preview-heading i{width:5px;height:5px;background:#e9a8bf;border-radius:50%;box-shadow:0 0 10px #ed87b244}.window{position:relative;aspect-ratio:1.52;isolation:isolate;overflow:hidden;border:1px solid #ffffff28;border-radius:13px;background:#17171b;box-shadow:0 40px 90px #0008,0 0 0 1px #0005}.scene,.artwork,.shade,.scanlines,.particles,.hud,.intro,.light-sweep,.end-screen{position:absolute;inset:0}.scene{overflow:hidden;z-index:2;background:#231923;will-change:opacity}.artwork{height:100%;width:100%;object-fit:cover;object-position:50% 49%;transform-origin:56% 52%;will-change:transform,opacity}.shade{background:linear-gradient(180deg,rgba(16,18,29,.63) 0%,rgba(23,20,35,.09) 24%,transparent 46%,rgba(25,20,36,.08) 68%,rgba(22,19,31,.66) 100%);pointer-events:none}.scanlines{opacity:.055;background:repeating-linear-gradient(transparent 0 3px,#201725 3px 4px);pointer-events:none}.light-sweep{inset:0;background:linear-gradient(110deg,transparent 43%,#fff4 50%,transparent 57%);pointer-events:none;opacity:0;will-change:transform,opacity}.hud{color:#fff3f6;font-family:"SFMono-Regular",Menlo,monospace;text-shadow:0 1px 7px #32203066}.corner{position:absolute;width:32px;height:32px;opacity:.75;border-color:#fce9f0;border-style:solid;border-width:0}.top-left{top:19px;left:19px;border-top-width:1.5px;border-left-width:1.5px}.top-right{top:19px;right:19px;border-top-width:1.5px;border-right-width:1.5px}.bottom-left{bottom:19px;left:19px;border-bottom-width:1.5px;border-left-width:1.5px}.bottom-right{bottom:19px;right:19px;border-bottom-width:1.5px;border-right-width:1.5px}.sync{position:absolute;top:8.5%;left:4%;width:23%;font-size:clamp(7px,.85vw,10px);letter-spacing:1.25px}.sync-label{display:flex;justify-content:space-between;margin-bottom:7px}.sync-track{height:4px;border:1px solid #ffedf284;background:#291d3025}.sync-fill{height:100%;width:100%;background:#fff0f6;transform:scaleX(0);transform-origin:left center;box-shadow:0 0 9px #ffd6e899}.sync-phase{display:block;margin-top:8px;font-size:7px;letter-spacing:1.6px;opacity:.57}.subtitle{position:absolute;left:12%;right:12%;bottom:7.5%;text-align:center;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;font-size:clamp(15px,1.9vw,21px);font-weight:500;letter-spacing:2px;text-shadow:0 2px 8px #291225b3;will-change:opacity,transform}.coordinates{display:flex;justify-content:space-between;position:absolute;bottom:3.6%;left:6%;right:6%;font-size:7px;letter-spacing:1.7px;opacity:.48}.particle{position:absolute;border-radius:50%;background:#ffecf4;will-change:transform,opacity;pointer-events:none}.intro{display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(ellipse,#312231,#19181f 65%);color:#f5d3e4;pointer-events:none}.intro-mark{font-size:60px;font-weight:200;line-height:1.2;text-shadow:0 0 32px #e994be55}.intro-label{font:8px Menlo,monospace;letter-spacing:4px;margin-top:23px;color:#ba9dae}.intro-line{height:1px;width:40px;background:#edc4d9;margin-top:17px;opacity:.5}.traffic{position:absolute;left:13px;top:13px;display:flex;gap:7px;z-index:4}.traffic i{width:12px;height:12px;border-radius:50%;background:#ff6059;box-shadow:inset 0 0 0 1px #0002}.traffic i:nth-child(2){background:#ffbd2e}.traffic i:nth-child(3){background:#28c840}.skip{position:absolute;z-index:5;right:25px;bottom:23px;border:0;padding:4px 6px;background:transparent;font-size:9px;letter-spacing:1px;color:#fff9;opacity:0;transition:opacity .2s}.window:hover .skip,.skip:focus-visible{opacity:1}.skip kbd{font:8px Menlo,monospace;border:1px solid #fff4;padding:1px 3px;border-radius:3px;margin-left:3px}.end-screen{z-index:1;display:flex;align-items:center;justify-content:center;flex-direction:column;background:radial-gradient(ellipse at 50% 45%,#30212c,#18171e 70%);text-align:center;padding:24px}.end-star{font-size:53px;color:#edb2cc;font-weight:200}.eyebrow{font:8px Menlo,monospace;letter-spacing:3px;color:#bc94aa;margin-top:25px}h1{font-size:25px;font-weight:400;letter-spacing:4px;margin:14px 0}.end-description{color:#95808d;font-size:12px;letter-spacing:1px;margin:8px 0 30px}.replay-end{border:1px solid #b18b9e44;border-radius:6px;background:#fff04a00;padding:10px 20px;font-size:12px;letter-spacing:1px;color:#ddc9d5}.replay-end span{margin-left:14px}.replay-end:hover{background:#fff1}.controls{display:flex;align-items:center;gap:22px;margin-top:24px;height:30px;color:#bfaab9}.playback-buttons{display:flex;gap:18px;align-items:center}.controls button{border:0;background:transparent;font-size:12px;white-space:nowrap;padding:5px 0}.controls button:hover{color:#ffdfed}#replay{font-size:20px;display:flex;gap:7px;align-items:center}#replay span{font-size:12px}#pause{min-width:28px}#timeline{flex:1;min-width:30px;height:3px;accent-color:#e0acc3;cursor:pointer}#elapsed{font:10px Menlo,monospace;white-space:nowrap;color:#d3bdc9}#elapsed span{color:#6e616c;margin-left:5px}.preview-note{font-size:10px;color:#766873;margin:16px 0 0;letter-spacing:.7px;display:flex;justify-content:space-between}.preview-note span{color:#5d545c}.finished .scene{pointer-events:none}.finished .skip{display:none}#asset-error{position:absolute;z-index:10;top:40%;left:10%;right:10%;padding:20px;background:#261b25;color:#fed9e6}.dslan-body.native{background:transparent;min-height:0}.dslan-body.native .preview{padding:0;width:100vw;height:100vh}.dslan-body.native .preview-heading,.dslan-body.native .controls,.dslan-body.native .preview-note,.dslan-body.native .traffic{display:none}.dslan-body.native .window{width:100%;height:100%;aspect-ratio:auto;border:0;border-radius:0;box-shadow:none}.dslan-body.native .sync{font-size:10px}.dslan-body.native .subtitle{font-size:20px}.dslan-body.native .native-launch{display:block}.dslan-body.native .end-screen .native-launch{margin-top:18px;border:0;background:none;color:#c59aae;font-size:12px}.dslan-body.launch-mode .replay-end{display:none}@media(max-width:600px){.preview{width:calc(100vw - 24px);padding-top:25px}.preview-heading{font-size:8px;letter-spacing:1.5px}.window{aspect-ratio:1.35}.sync{width:29%;top:11%;font-size:7px}.traffic{gap:5px;left:11px;top:11px}.traffic i{width:9px;height:9px}.corner{width:21px;height:21px}.controls{gap:14px}.playback-buttons{gap:12px}.subtitle{font-size:15px;bottom:10%}.coordinates{font-size:5px;letter-spacing:1px}h1{font-size:20px;letter-spacing:2px}.preview-note{font-size:9px}.sync-phase{font-size:5px}.skip{right:20px;bottom:18px}}@media(prefers-reduced-motion:reduce){.artwork,.particle,.light-sweep{will-change:auto}.scanlines{display:none}}
/* Keep the completed screen out of keyboard navigation during playback. */
.end-screen{visibility:hidden}.finished .end-screen{visibility:visible}.scanlines{opacity:.022}
/* Boot sequence: one shared clock drives every stage, including stroke drawing. */
.scene{background:#08060d}.artwork{opacity:0;object-position:50% 50%;transform-origin:50% 50%}
.line-art{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none}
.transition-flash{position:absolute;inset:0;background:#fff8fc;opacity:0;pointer-events:none}
.intro{background:none;color:#d980a7;opacity:1}
.pulse{position:absolute;left:50%;top:50%;width:110px;height:110px;transform:translate(-50%,-50%)}
.pulse i{position:absolute;inset:0;border:2px solid #bd5d8980;border-radius:50%;box-shadow:0 0 6px #b8608920}
.pulse b{position:absolute;left:50%;top:50%;width:8px;height:8px;transform:translate(-50%,-50%);border-radius:50%;background:#ee96bc;box-shadow:0 0 12px #ee79b288}
.identity{position:absolute;left:50%;top:50%;width:44%;transform:translate(-50%,-43%);text-align:center;opacity:0}
.radar{position:relative;width:82%;aspect-ratio:1;margin:auto}
.dial{position:absolute;inset:0;width:100%;height:100%;fill:none;stroke:#c27697;stroke-width:1;overflow:visible}
.dial .dashed{stroke-dasharray:9 12;stroke:#8f819e;opacity:.4}.dial .ticks{stroke-width:1.6}.crosshair{stroke:#c5b2c4;opacity:.65}
.avatar-frame{position:absolute;inset:21%;padding:8px;border:1px solid #cb7b9f;box-shadow:0 0 18px #f18ab514}
.avatar-frame:before,.avatar-frame:after{content:"";position:absolute;inset:-4px;border:2px solid #d593b7;clip-path:polygon(0 0,14% 0,14% 1%,1% 1%,1% 14%,0 14%,0 0,100% 0,100% 14%,99% 14%,99% 1%,86% 1%,86% 0,100% 0,100% 100%,86% 100%,86% 99%,99% 99%,99% 86%,100% 86%,100% 100%,0 100%,0 86%,1% 86%,1% 99%,14% 99%,14% 100%,0 100%)}
.avatar{display:block;width:100%;height:100%;object-fit:cover;image-rendering:pixelated}
.reticle{position:absolute;width:14%;height:6%;border:solid #817581;border-width:0;opacity:.7}.reticle.tl{left:-16%;top:17%;border-top-width:1px;border-left-width:1px}.reticle.tr{right:-16%;top:17%;border-top-width:1px;border-right-width:1px}.reticle.bl{left:-16%;bottom:3%;border-bottom-width:1px;border-left-width:1px}.reticle.br{right:-16%;bottom:3%;border-bottom-width:1px;border-right-width:1px}
.wave{display:block;width:95%;height:22px;margin:12px auto -4px;fill:none;stroke:#d087a6;stroke-width:1.4;opacity:.7}
.boot-title{font-family:"Songti SC","STSong",serif;font-size:clamp(25px,4.9vw,52px);font-weight:700;letter-spacing:.32em;padding-left:.32em;line-height:1.25;color:#d9d8e2;text-shadow:2px 0 #853d62,-2px 0 #8cc3cd}
.boot-caption{font:7px Menlo,monospace;letter-spacing:6px;color:#74617b;opacity:.5;margin-top:12px;white-space:nowrap}
.boot-grid{position:absolute;inset:20% 23% 18%;background-image:linear-gradient(#7560800c 1px,transparent 1px),linear-gradient(90deg,#7560800c 1px,transparent 1px);background-size:34px 34px;mask-image:radial-gradient(ellipse,black,transparent 72%);pointer-events:none}
.boot-corners .corner{border-color:#9c456c;opacity:.65}.boot-logs{position:absolute;left:4%;bottom:6%;font:clamp(5px,.75vw,9px)/1.9 Menlo,monospace;letter-spacing:.45px;color:#968391;opacity:.55}.boot-logs div{opacity:0}
.skip{opacity:.5;color:#968391;font:8px Menlo,monospace;letter-spacing:1.5px;bottom:5%;right:4%}.window:hover .skip{opacity:.85}
@media(max-width:600px){.identity{width:53%}.boot-title{font-size:27px}.boot-caption{font-size:5px;letter-spacing:3px}.wave{margin-top:5px;height:12px}.avatar-frame{padding:4px}.boot-logs{font-size:5px}.skip{font-size:5px;letter-spacing:.5px}.pulse{width:70px;height:70px}}
.hud,.shade{opacity:0}
#image-settings{position:absolute;z-index:5;top:18px;right:23px;background:#100b1288;border:1px solid #a7839944;border-radius:5px;color:#c4a6b8;font-size:10px;padding:6px 10px;cursor:pointer}
.dslan-body.launch-mode #image-settings{display:none}
#settings-dialog{color:#eddfE9;background:#18131b;border:1px solid #665060;border-radius:14px;width:min(590px,90vw);max-height:90vh;padding:30px;box-shadow:0 30px 100px #0009;overflow:auto}
#settings-dialog::backdrop{background:#050309cc;backdrop-filter:blur(12px)}
#settings-dialog .eyebrow{margin:0 0 12px}#settings-title{margin:0;font-size:24px;letter-spacing:1px;font-weight:500}.settings-description{font-size:12px;color:#9c8796;margin:12px 0 24px}
.settings-close{position:absolute;right:16px;top:12px;font-size:26px;border:0;background:none;color:#a18a99}
.image-choices{display:grid;grid-template-columns:1fr 1fr;gap:16px}.image-choice{position:relative;display:flex;align-items:flex-start;flex-direction:column;padding:12px;background:#241b26;border:1px solid #63465c66;border-radius:8px;cursor:pointer;overflow:hidden}.image-choice>img{width:100%;height:130px;object-fit:cover;border-radius:4px;margin-bottom:14px}#avatar-preview{object-fit:contain;background:#100b13}.image-choice>span{font-size:13px}.image-choice>small{font-size:10px;color:#a18a99;margin:7px 0 16px}.image-choice .choose-label{font-size:11px;color:#edb4d0}.image-choice input{position:absolute;inset:0;opacity:0;width:100%;height:100%;cursor:pointer}.image-choice:focus-within{outline:2px solid #d8a4bf;outline-offset:2px}
#settings-status{font-size:11px;color:#b397a8;line-height:1.7;min-height:38px;margin:20px 0 16px}.settings-actions{display:flex;justify-content:space-between;gap:15px}.settings-actions button{padding:10px 14px;font-size:11px;border-radius:5px;border:1px solid #9b708b55;background:none}.settings-actions #preview-images{background:#d7a4c0;color:#251b24;border:0}.settings-actions button:disabled{opacity:.4;cursor:wait}
.dslan-body.embedded{background:#08060d;min-height:0}.dslan-body.embedded .preview{padding:0;width:100vw;height:100vh}.dslan-body.embedded .preview-heading,.dslan-body.embedded .controls,.dslan-body.embedded .preview-note,.dslan-body.embedded .traffic{display:none}.dslan-body.embedded .window{width:100%;height:100%;aspect-ratio:auto;border:0;border-radius:0;box-shadow:none}.dslan-body.embedded .scene{inset:0}.dslan-body.embedded #image-settings{top:40px}
.dslan-body.embedded .window:before{content:"";position:absolute;z-index:4;top:0;left:0;right:0;height:32px;-webkit-app-region:drag;pointer-events:none}
.scene{transform-origin:50% 50%}.shutter-line{position:absolute;z-index:4;top:50%;left:0;right:0;height:2px;background:#fff9fd;box-shadow:0 0 6px #fff,0 0 18px #f5cee8;opacity:0;transform-origin:center;pointer-events:none}
.closing .end-screen{visibility:visible}.closing #image-settings,.closing .skip{visibility:hidden}
.dslan-body.embedded.closing,.dslan-body.native.closing,.dslan-body.embedded.closing .window,.dslan-body.native.launch-mode.closing .window{background:transparent}
.dslan-body.embedded .end-screen,.dslan-body.native.launch-mode.closing .end-screen{visibility:hidden}
:root:has(.dslan-body.embedded.closing),:root:has(.dslan-body.native.launch-mode.closing){background:transparent}
#image-settings{display:none}
.finished #image-settings{display:block;visibility:visible}
#restore-appearance{margin-top:20px;width:100%;border:0;background:none;color:#ad95a7;font-size:11px;padding:8px}
#restore-appearance[hidden]{display:none}
.wallpaper-setting{display:grid;grid-template-columns:1fr auto;gap:10px;margin-top:20px;font-size:12px;color:#c7aebb}.wallpaper-setting input{grid-column:1/-1;width:100%;accent-color:#d7a4c0}.wallpaper-setting small{grid-column:1/-1;color:#a18a99;font-size:10px;line-height:1.6}.wallpaper-setting output{font:11px Menlo,monospace}
.text-settings{display:grid;grid-template-columns:1fr 1fr;gap:14px 16px;margin-top:20px}.text-settings label{display:flex;flex-direction:column;gap:8px;min-width:0;font-size:12px;color:#c7aebb}.text-settings input{width:100%;min-width:0;padding:10px 11px;border:1px solid #63465c;border-radius:6px;background:#241b26;color:#f7eef2;font:inherit;font-size:13px}.text-settings small{font-size:10px;color:#a18a99}.text-wide{grid-column:1/-1}.boot-title{overflow-wrap:anywhere}.boot-title.long-title{font-size:clamp(18px,2.5vw,30px);letter-spacing:.12em;padding-left:.12em}.boot-caption{white-space:normal;overflow-wrap:anywhere;line-height:1.7}.subtitle{overflow-wrap:anywhere;line-height:1.5}
@media(max-width:480px){.text-settings{grid-template-columns:1fr}#settings-dialog{padding:24px 18px}.settings-actions{gap:8px}.settings-actions button{padding:10px 8px}}


/* 2A：整层上下挤压成线，再横向缩成点后进入 Codex */
.revealing .scene{will-change:transform,opacity;transform-origin:50% 50%;}


/* 视觉预览 v1：只改变动画视觉，不修改播放时序、壁纸或文案。 */
:root { --polish-pink:#efb5d1; --polish-blue:#a9d7ef; --polish-muted:#a39aac; font-family:'Segoe UI','Microsoft YaHei UI',sans-serif; }
.scene { background:radial-gradient(ellipse at 50% 43%,#222337 0%,#11131f 44%,#080a12 83%); }
.identity { width:min(40vw,58vh,520px); }
.dial { stroke:var(--polish-blue); stroke-width:.85; }
.dial .dashed { stroke:var(--polish-pink); opacity:.48; stroke-dasharray:3 10; }
.dial .ticks { stroke-width:1.2; }
.crosshair { stroke:#c2deed; opacity:.58; }
.avatar-frame { border-color:#dab5cf; padding:9px; box-shadow:0 0 22px #9dcdea16,inset 0 0 12px #efb5d10b; }
.avatar-frame:before,.avatar-frame:after { border-color:#b5d4e8; border-width:1px; }
.avatar { image-rendering:auto; }
.reticle { border-color:#a6c9e1; opacity:.62; }
.wave { stroke:#edb8d1; stroke-width:1.1; }
.boot-title { font-family:'Segoe UI','Microsoft YaHei UI',sans-serif; font-weight:300; font-size:clamp(32px,4vw,48px); letter-spacing:.26em; padding-left:.26em; color:#f3eaf4; text-shadow:0 0 22px #bdc7ef24; margin-top:9px; }
.boot-caption { font-family:Consolas,'Cascadia Mono',monospace; font-size:9px; letter-spacing:3px; color:#bfc5d9; margin-top:12px; }
.boot-grid { background-image:linear-gradient(#a9d7ef0d 1px,transparent 1px),linear-gradient(90deg,#a9d7ef0d 1px,transparent 1px); background-size:40px 40px; }
.boot-corners .corner { border-color:#b2c9df; width:25px; height:25px; }
.boot-logs { left:4%; bottom:6%; color:#c2b9cc; font:clamp(8px,.8vw,11px)/1.95 Consolas,'Cascadia Mono',monospace; letter-spacing:.5px; }
.pulse i { border:1px solid #a9d7ef75; box-shadow:0 0 12px #a9d7ef10; }
.pulse b { background:#f2c1d8; box-shadow:0 0 18px #efb5d160; }
.hud { font-family:Consolas,'Cascadia Mono',monospace; color:#fff4fa; text-shadow:0 1px 7px #18213180; }
.hud .corner { width:25px; height:25px; border-color:#e6eaf7; }
.sync { top:8.5%; left:4%; width:clamp(190px,23%,300px); padding:14px 16px; border:1px solid #e0d6e52e; border-radius:8px; background:linear-gradient(120deg,#172032b3,#3020398c); box-shadow:0 8px 30px #14172320; font-size:10px; letter-spacing:1.4px; }
.sync-label { margin-bottom:10px; }
#ratio { color:#e6f4ff; font-variant-numeric:tabular-nums; letter-spacing:.6px; }
.sync-track { height:3px; border:0; border-radius:8px; overflow:hidden; background:#e8eff02b; }
.sync-fill { background:linear-gradient(90deg,#acd8f0,#f3bfd9); box-shadow:none; }
.sync-phase { font-size:8px; letter-spacing:1.6px; margin-top:10px; opacity:.72; }
.subtitle { font-family:'Segoe UI','Microsoft YaHei UI',sans-serif; font-size:clamp(16px,1.9vw,22px); font-weight:400; letter-spacing:3px; text-shadow:0 2px 12px #15202b99; }
.coordinates { font-size:8px; letter-spacing:1.5px; opacity:.65; }
.skip { color:#d4c9d8; font-family:Consolas,monospace; font-size:9px; letter-spacing:1.2px; padding:8px 10px; border:1px solid #d4cad325; border-radius:5px; background:#10162440; }
.scanlines { opacity:.012; }
.shutter-line { background:#eef6ff; box-shadow:0 0 7px #dbeeff,0 0 20px #efb5d159; }
@media(max-width:600px) { .identity { width:min(58vw,58vh); } .boot-caption { font-size:7px; letter-spacing:2px; } .boot-logs { font-size:7px; } .sync { width:180px; padding:10px 12px; } }



/* 按产品规格：改用系统字体，不携带自定义字体文件，减小注入体积。 */
:root {
  font-family: "Microsoft YaHei UI", "Microsoft YaHei", "Segoe UI", system-ui, sans-serif !important;
}

.hud,
.preview-heading,
.coordinates,
.sync,
.boot-caption,
.boot-logs,
.eyebrow,
.skip,
.controls,
#elapsed {
  font-family: "Cascadia Mono", Consolas, "Courier New", monospace !important;
}

:host, .dslan-body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #09070c;
}

.dslan-body {
  display: block;
}

.preview {
  width: 100vw;
  height: 100vh;
  padding: 0;
}

.window {
  width: 100vw;
  height: 100vh;
  aspect-ratio: auto;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.preview-heading,
.preview-note,
.controls,
.traffic,
#image-settings {
  display: none !important;
}

.dslan-body.preview-mode .preview-heading {
  display: flex !important;
  position: fixed;
  z-index: 20;
  left: 30px;
  right: 30px;
  top: 18px;
  color: #d6c4d0;
  pointer-events: none;
}

.dslan-body.preview-mode .preview-note {
  display: block !important;
  position: fixed;
  z-index: 20;
  left: 30px;
  bottom: 8px;
  color: #8f7d89;
  font-size: 10px;
}

.dslan-body.preview-mode .controls {
  display: flex !important;
  position: fixed;
  z-index: 21;
  left: 30px;
  right: 30px;
  bottom: 26px;
}

.window.outro .scene {
  animation: launcherOutro 500ms ease forwards;
}

@keyframes launcherOutro {
  from { opacity: 1; transform: scale(1); filter: blur(0); }
  to { opacity: 0; transform: scale(1.035); filter: blur(4px); }
}
/* 动画结束后保留设置入口，方便调整背景显现程度 */
.dslan-body.native .window.finished #image-settings {
